sys_variable_value.value:
(function execute(inputs, outputs) {

 var vendor = VendorUtils.getVendorDetails(inputs.vendorSysId);

    if (vendor) {
        outputs.name = vendor.name;
        outputs.email = vendor.email;
       
    }


})(inputs, outputs);

